+fn hexa(c: [Point3; 8]) -> Vec<Triangle> {
+    let quads = [[0, 3, 2, 1], [4, 5, 6, 7], [0, 1, 5, 4], [1, 2, 6, 5], [2, 3, 7, 6], [3, 0, 4, 7]];
+    let mut f = Vec::new();
+    for q in quads {
+        f.push(Triangle::new(c[q[0]], c[q[1]], c[q[2]]));
+        f.push(Triangle::new(c[q[0]], c[q[2]], c[q[3]]));
+    }
