+        p(0.0, 0.0, 0.0),
+        p(40.0, 0.0, 0.0),
+        p(40.0, 30.0, 0.0),
+        p(0.0, 30.0, 0.0),
+        p(0.0, 0.0, 10.0),
+        p(40.0, 0.0, 10.0 - drop),
+        p(40.0, 30.0, 10.0 - drop),
+        p(0.0, 30.0, 10.0),
+    ]))
